{"mappings": [{"technique_id": "T1528", "technique_name": "Steal Application Access Token", "tactic": "Credential Access", "confidence": 0.7, "rationale": "Changing an app's redirect/reply URI (AppAddress) to a domain the attacker controls, a dangling domain, or a wildcard lets OAuth authorization codes and tokens be sent to the attacker. This is the main token-theft risk the rule describes."}, {"technique_id": "T1078.004", "technique_name": "Valid Accounts: Cloud Accounts", "tactic": "Persistence", "confidence": 0.5, "rationale": "Changing an application's URI configuration in Entra ID requires a privileged cloud identity. An unplanned change may mean a compromised admin or app-owner account is being used to keep access."}, {"technique_id": "T1098", "technique_name": "Account Manipulation", "tactic": "Persistence", "confidence": 0.35, "rationale": "Modifying an application or service principal's configuration can be a way to tamper with a cloud identity object so the attacker keeps or widens access through that application."}]}
