{"mappings": [{"technique_id": "T1003.008", "technique_name": "OS Credential Dumping: /etc/passwd and /etc/shadow", "tactic": "Credential Access", "confidence": 0.5, "rationale": "Symlinking /etc/passwd into a location that a privileged or web-facing process reads lets an attacker get the account file's contents back, for example through a web root, a log, or an upload directory."}, {"technique_id": "T1068", "technique_name": "Exploitation for Privilege Escalation", "tactic": "Privilege Escalation", "confidence": 0.35, "rationale": "Symlinks to /etc/passwd are a classic symlink or TOCTOU attack. When a privileged process writes through the link, the attacker can modify /etc/passwd and add a root user."}, {"technique_id": "T1204.001", "technique_name": "User Execution: Malicious Link", "tactic": "Execution", "confidence": 0.2, "rationale": "The upstream Sigma rule tags this detection with T1204.001. It is included for consistency with that rule, but it fits the observed behavior poorly."}]}
